/**
 * `/guide`: the step-by-step visual walkthrough. Twelve real screenshots, served
 * from the Worker itself (src/guide-images.ts, regenerated by
 * scripts/build-guide-images.mjs). Public and identical for everyone, like `/`.
 *
 * Image URLs carry `?v=<content hash>` and are served `immutable`, so a re-shoot
 * changes the hash and busts every cache. Dimensions are written into each <img>
 * so the page does not jump while they load.
 */

const TITLE = "Step-by-step guide · rtfx.pro";
