  "with people or a revocable link, and see who opened it.";

const IMMUTABLE = "public, max-age=31536000, immutable";

/** Serve `/guide/<name>.webp`; anything else under /guide/ is a 404. */
export function guideImageResponse(file: string): Response {
  const m = /^([a-z0-9-]+)\.webp$/.exec(file);
  const img = m ? Object.hasOwn(GUIDE_IMAGES, m[1]) && GUIDE_IMAGES[m[1]!] : undefined;
  if (!img) return new Response("Not found", { status: 404 });
  return new Response(Uint8Array.from(atob(img.base64), (ch) => ch.charCodeAt(0)), {
    headers: {
      "Content-Type": "image/webp",
      "Cache-Control": IMMUTABLE,
      "X-Content-Type-Options": "nosniff",
    },
  });
}

