function step(n: number, s: Shot, first: boolean): string {
  const cap = s.caption ? `<figcaption>${s.caption}</figcaption>` : "";
  return `<li id="step-${n}">
        <div class="step-head"><span class="step-n" aria-hidden="true">${n}</span><p><span class="sr-only">Step ${n}. </span>${s.text}</p></div>
        ${s.quote ? `<blockquote class="prompt">&ldquo;${s.quote}&rdquo;</blockquote>` : ""}
        <figure${s.phone ? ' class="phone"' : ""}>
          <img src="/guide/${s.name}.webp?v=${GUIDE_IMAGES[s.name]!.hash}" width="${s.width}" height="${s.height}" alt="${esc(s.alt)}"${first ? "" : ' loading="lazy"'} decoding="async">${cap}
        </figure>
      </li>`;
}

export function guidePage(env: Env): string {
  let n = 0;
  const part = (id: string, letter: string, title: string, shots: Shot[]): string => {
    const items = shots.map((s) => step(++n, s, n === 1)).join("\n      ");
    return `<section id="${id}" class="part">
      <h2><span>${letter}</span>${title}</h2>
      <ol class="steps" start="${n - shots.length + 1}">
      ${items}
      </ol>
    </section>`;
  };

  const body = `
    ${siteHeader("guide")}

    <main id="main">
    <section class="hero">
      <h1>${H1}</h1>
      <p class="lead">Every screenshot below is the real thing — Claude Desktop and claude.ai show the same screens. About three minutes end to end.</p>
      <div class="mcp-box">
        <code id="mcp-url">${MCP_URL}</code>
        <button type="button" class="ghost" data-copy="${MCP_URL}">Copy</button>
      </div>
      <p class="jump"><a href="#connect">A. Connect</a> <a href="#publish">B. Publish</a> <a href="#share">C. Share</a> <a href="#views">D. See who opened it</a></p>
      ${guideVideo()}
    </section>

    ${part("connect", "A", "Connect", A)}
    ${part("publish", "B", "Publish", B)}
    ${part("share", "C", "Share", C)}
    ${part("views", "D", "See who opened it", D)}

    <section class="final">
      <h2>Ready when you are.</h2>
      <div class="cta">
        <a class="link-button" href="/signup" data-cta="signup-final">Start free</a>
        <a class="ghost link-button" href="/#start" data-cta="overview">Back to the overview</a>
      </div>
    </section>
    </main>

    ${siteFooter()}
    ${cookieNotice()}
    <script>${CONSENT_SCRIPT}</script>
    <script>${COPY_SCRIPT}</script>`;
  return layout(TITLE, body, STYLE, {
    description: DESCRIPTION,
    canonical: canonicalUrl(env, "/guide"),
    image: canonicalUrl(env, "/og.png"),
    socialTitle: `${SITE.name} — step-by-step guide`,
  });
}
